#!/usr/bin/env python3
import os, re, sys, json, sqlite3

RED = "[redacted]"
A = 48 * 100
B = 35 * 10
comA = format(A, ",")
strA = str(A)
strB = str(B)
INCOME_WORDS = re.compile(r'\btake[-\s]?home\b|\bincome\b', re.I)
DEBT_WORDS = re.compile(r'\bdebts?\b', re.I)
ALWAYS = [
    re.compile(r'\$' + comA + r'\b'),
    re.compile(r'\$' + strA + r'\b'),
    re.compile(r'\$' + strB + r'\b'),
]
NEAR_INCOME = re.compile(r'\b(?:' + comA + r'|' + strA + r')\b')
NEAR_DEBT = re.compile(r'\b' + strB + r'\b')
WORDS = [
    (re.compile(r'\btake[-\s]?home\b', re.I), RED),
    (re.compile(r'\bincome\b', re.I), RED),
    (re.compile(r'\bdebts?\b', re.I), RED),
]

def redact_text(t):
    n = 0
    for rx in ALWAYS:
        t, k = rx.subn(RED, t)
        n += k
    out = []
    for line in t.split('\n'):
        if INCOME_WORDS.search(line):
            line, k = NEAR_INCOME.subn(RED, line)
            n += k
        if DEBT_WORDS.search(line):
            line, k = NEAR_DEBT.subn(RED, line)
            n += k
        out.append(line)
    t = '\n'.join(out)
    for rx, rep in WORDS:
        t, k = rx.subn(rep, t)
        n += k
    return t, n

def process_sqlite(path, check):
    counts = 0
    con = sqlite3.connect(path)
    try:
        cur = con.cursor()
        tables = [r[0] for r in cur.execute("select name from sqlite_master where type='table'")]
        for tb in tables:
            cols = cur.execute('pragma table_info("%s")' % tb).fetchall()
            for c in cols:
                col, typ = c[1], (c[2] or '').upper()
                if 'CHAR' not in typ and typ not in ('TEXT', 'JSON'):
                    continue
                try:
                    rows = cur.execute('select rowid, "%s" from "%s"' % (col, tb)).fetchall()
                except Exception:
                    continue
                for rid, val in rows:
                    if not isinstance(val, str):
                        continue
                    new, n = redact_text(val)
                    if n:
                        counts += n
                        if not check:
                            cur.execute('update "%s" set "%s"=? where rowid=?' % (tb, col), (new, rid))
        if not check:
            con.commit()
    finally:
        con.close()
    return counts

def main():
    check = '--check' in sys.argv
    home = os.path.expanduser('~')
    roots = []
    for p in (
        os.path.join(os.environ.get('XDG_DATA_HOME', os.path.join(home, '.local', 'share')), 'opencode'),
        os.path.join(home, '.local', 'share', 'opencode'),
        os.path.join(home, '.cache', 'opencode'),
    ):
        if os.path.isdir(p) and p not in roots:
            roots.append(p)
    total = 0
    files = 0
    for root in roots:
        for dirpath, _, names in os.walk(root):
            for name in names:
                path = os.path.join(dirpath, name)
                if path.endswith('-shm') or path.endswith('-wal'):
                    continue
                try:
                    with open(path, 'rb') as f:
                        data = f.read()
                except Exception:
                    continue
                if data[:15] == b'SQLite format 3':
                    c = process_sqlite(path, check)
                    if c:
                        files += 1
                        total += c
                        print('%s: %d' % (path, c))
                    continue
                if b'\x00' in data:
                    continue
                text, n = redact_text(data.decode('utf-8', 'surrogateescape'))
                if not n:
                    continue
                if check:
                    files += 1
                    total += n
                    print('%s: %d' % (path, n))
                    continue
                if path.endswith('.json'):
                    try:
                        json.loads(text)
                    except Exception:
                        print('SKIP (json validate failed): %s' % path)
                        continue
                tmp = path + '.tmp-redact'
                try:
                    with open(tmp, 'wb') as f:
                        f.write(text.encode('utf-8', 'surrogateescape'))
                    os.replace(tmp, path)
                    files += 1
                    total += n
                    print('%s: %d' % (path, n))
                except Exception as e:
                    print('error writing %s: %s' % (path, e))
    print('%s: %d in %d files' % ('remaining occurrences' if check else 'redacted', total, files))

if __name__ == '__main__':
    main()

